WITH base AS (SELECT *, ROUND(pressure / humidity, 2) AS pressure_per_humidity, CASE WHEN device_code IN ('DV-03', 'DV-02') THEN 'Priority' ELSE 'Other' END AS device_code_group FROM device_readings WHERE pressure > 1012), prev_events AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM base), flagged AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL 1 HOUR THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessions_device_readings AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, COUNT(*) FILTER (WHERE device_code = 'DV-03') AS dv_03_rows, COUNT(*) AS cnt, ROUND(AVG(temp_c), 2) AS avg_temp_c FROM sessions_device_readings GROUP BY hour_window ORDER BY cnt DESC NULLS LAST;
